INSERT INTO feature VALUES('build-entries','storage','A built output as a tree of entries in the store',NULL,'partial','notable',NULL,'A directory, a file or a symbolic link reads into the store as an entry: a directory is one record tree keyed by entry name, and a file is a blob, its bytes cut by the byte profile of the chunker, whose Gear state shifts left, each piece one value of the value plane. A file reads one buffer at a time, each piece committed at its cut, so a read holds one buffer and one piece, never the file. An entry''s address is the digest of its encoding, so a tree read again writes no object and keeps its address, and one byte put before a file writes only the pieces near it and the trees above it. An entry writes out into a new directory with the same bytes and the executable bit, each tree checked against its manifest and each piece by its digest, and a name that would leave the directory is refused by name. An output holds its root entry and the addresses it references, its identity the root''s address. A bench reads many files into one store at once on many threads, and states the rate of its puts beside the rate of the fold of one writer.','storage-store storage-chunker','crates/storage-store/tests/entries.rs crates/storage-chunker/tests/byte.rs',NULL,'#6591');
